# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">YERYÜZÜNDE SICAKLIĞIN DAĞILIŞINI ETKİLEYEN TEMEL FAKTÖRLER</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">1. GÜNEŞ IŞINLARININ DÜŞME AÇISI</text>\n  <text x="35" y="94" font-size="11" font-weight="bold" fill="#78350f">• Dünyanın Şekli (Enlem Etkisi):</text>\n  <text x="45" y="110" font-size="10.5" fill="#92400e">Ekvator\'dan kutuplara doğru açı küçülür, sıcaklık azalır.</text>\n  <text x="35" y="132" font-size="11" font-weight="bold" fill="#78350f">• Eksen Eğikliği ve Yıllık Hareket:</text>\n  <text x="45" y="148" font-size="10.5" fill="#92400e">Mevsimlik sıcaklık farklarını oluşturur (Yaz / Kış).</text>\n  <text x="35" y="170" font-size="11" font-weight="bold" fill="#78350f">• Günlük Hareket (Eksen Hareketi):</text>\n  <text x="45" y="186" font-size="10.5" fill="#92400e">Gün içi sıcaklık değişimini (en sıcak 13.00-14.00) sağlar.</text>\n  <text x="35" y="208" font-size="11" font-weight="bold" fill="#78350f">• Yer Şekilleri (Bakı ve Eğim):</text>\n  <text x="45" y="224" font-size="10.5" fill="#92400e">Güneşe dönük yamaç (bakı) daha fazla ısınır.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">2. DİĞER COĞRAFİ VE ATMOSFERİK FAKTÖRLER</text>\n  <text x="375" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">• Yükselti (Troposfer Özelliği):</text>\n  <text x="385" y="110" font-size="10.5" fill="#1d4ed8">Yerden yükseldikçe her 200 m\'de sıcaklık 1 °C (1000 m\'de 5 °C) azalır.</text>\n  <text x="375" y="132" font-size="11" font-weight="bold" fill="#1e3a8a">• Kara ve Denizlerin Dağılışı:</text>\n  <text x="385" y="148" font-size="10.5" fill="#1d4ed8">Karalar erken ve çok ısınır/soğur; denizler geç ısınır/soğur.</text>\n  <text x="375" y="170" font-size="11" font-weight="bold" fill="#1e3a8a">• Okyanus Akıntıları ve Rüzgârlar:</text>\n  <text x="385" y="186" font-size="10.5" fill="#1d4ed8">Gulf Stream (sıcak), Labrador/Humboldt (soğuk) etki yapar.</text>\n  <text x="375" y="208" font-size="11" font-weight="bold" fill="#1e3a8a">• Atmosferik Nem (Su Buharı):</text>\n  <text x="385" y="224" font-size="10.5" fill="#1d4ed8">Aşırı ısınma ve soğumayı önler, sıcaklık farkını azaltır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BAKI ETKİSİ (KUZEY YARIM KÜRE) VE YÜKSELTİ - SICAKLIK İLİŞKİSİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">KUZEY YARIM KÜREDE (TÜRKİYE) BAKI YÖNÜ</text>\n  <polygon points="60,185 165,90 270,185" fill="#bbf7d0" stroke="#15803d" stroke-width="2"/>\n  <circle cx="300" cy="78" r="18" fill="#facc15" stroke="#ca8a04" stroke-width="2"/>\n  <line x1="280" y1="90" x2="215" y2="132" stroke="#eab308" stroke-width="2.5" stroke-dasharray="4,3"/>\n  <line x1="285" y1="100" x2="235" y2="152" stroke="#eab308" stroke-width="2.5" stroke-dasharray="4,3"/>\n  <text x="95" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">KUZEY (Dulda)</text>\n  <text x="235" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">GÜNEY (Bakı)</text>\n  <text x="35" y="218" font-size="10.5" fill="#14532d">• Güney yamaçta: Güneşlenme süresi uzun, sıcaklık yüksek,</text>\n  <text x="43" y="232" font-size="10.5" fill="#14532d">kalıcı kar sınırı, tarım ve yerleşme üst sınırı YÜKSEKTİR.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">GERÇEK VE İNDİRGENMİŞ SICAKLIK HESABI</text>\n  <text x="375" y="94" font-size="11" font-weight="bold" fill="#581c87">Formül: Sıcaklık Farkı = Yükselti (m) / 200</text>\n  <text x="375" y="116" font-size="11" font-weight="bold" fill="#581c87">İndirgenmiş Sıcaklık = Gerçek Sıcaklık + (Yükselti / 200)</text>\n  <rect x="375" y="130" width="290" height="95" rx="8" fill="#ffffff" stroke="#c084fc" stroke-width="1.5"/>\n  <text x="388" y="150" font-size="11" font-weight="bold" fill="#6b21a8">Örnek Uygulama (Erzurum - 1800 m):</text>\n  <text x="388" y="170" font-size="10.5" fill="#581c87">• Gerçek sıcaklık = -2 °C, Yükselti = 1800 m</text>\n  <text x="388" y="190" font-size="10.5" fill="#581c87">• Yükselti farkı etkisi = 1800 / 200 = +9 °C</text>\n  <text x="388" y="210" font-size="10.5" font-weight="bold" fill="#b91c1c">• İndirgenmiş Sıcaklık = -2 + 9 = +7 °C olur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DÜNYA İZOTERM (EŞ SICAKLIK) HARİTALARININ TEMEL ÖZELLİKLERİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">KUZEY VE GÜNEY YARIM KÜRE FARKI</text>\n  <text x="40" y="96" font-size="11" fill="#1e3a8a">• Kuzey Yarım Küre\'de karalar geniş yer kapladığı için</text>\n  <text x="48" y="112" font-size="11" font-weight="bold" fill="#1d4ed8">izoterm eğrileri daha fazla girinti-çıkıntı yapar.</text>\n  <text x="40" y="138" font-size="11" fill="#1e3a8a">• Güney Yarım Küre\'de okyanuslar geniş yer tuttuğu için</text>\n  <text x="48" y="154" font-size="11" font-weight="bold" fill="#1d4ed8">izoterm eğrileri paralellere daha düz (uyumlu) uzanır.</text>\n  <text x="40" y="180" font-size="11" fill="#1e3a8a">• Termik Ekvator (en sıcak noktaları birleştiren çizgi)</text>\n  <text x="48" y="196" font-size="11" font-weight="bold" fill="#b91c1c">karaların fazlalığından dolayı KYK\'ye doğru sapar.</text>\n  <text x="40" y="222" font-size="10.5" fill="#1e3a8a">• İndirgenmiş haritalarda yükselti faktörü devre dışıdır!</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9f1239">OCAK VE TEMMUZ İZOTERM YORUMLARI</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#881337">• Temmuz Ayı (KYK Yaz, GYK Kış):</text>\n  <text x="383" y="114" font-size="10.5" fill="#9f1239">Dünyanın en sıcak yerleri Yengeç Dönencesi çevresindeki</text>\n  <text x="383" y="130" font-size="10.5" fill="#9f1239">karalardır (Büyük Sahra, Arabistan, Orta Asya).</text>\n  <text x="375" y="156" font-size="11" font-weight="bold" fill="#881337">• Ocak Ayı (KYK Kış, GYK Yaz):</text>\n  <text x="383" y="174" font-size="10.5" fill="#9f1239">Dünyanın en soğuk yeri Sibirya\'dır (aşırı karasallık);</text>\n  <text x="383" y="190" font-size="10.5" fill="#9f1239">en sıcak yerler Oğlak Dönencesi karalarıdır.</text>\n  <text x="375" y="218" font-size="10.5" font-weight="bold" fill="#15803d">• Okyanus akıntıları kıta kıyılarında eğrileri büker.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
